{"summary":"Add D3 visualization logic for bubble chart, table, and interactions","security_risk":"MEDIUM","command":"create","path":"/root/output/js/visualization.js","file_text":"/* global d3 */

(() => {
  const DATA_PATH = {
    descriptions: 'data/stock-descriptions.csv',
    historyDir: 'data/indiv-stock'
  };

  const svg = d3.select('#bubble-svg');
  const legendEl = d3.select('#legend');
  const tableBody = d3.select('#stock-table tbody');
  const tooltip = d3.select('#tooltip');

  const historyCache = new Map();
  let selectedTicker = null;

  function toNumber(v) {
    if (v == null) return NaN;
    const s = String(v).trim();
    if (!s) return NaN;
    const n = Number(s);
    return Number.isFinite(n) ? n : NaN;
  }

  function formatMarketCap(n) {
    if (!Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    const fmt = (x, unit) => `${d3.format('.3~g')(x)}${unit}`;
    if (abs >= 1e12) return fmt(n / 1e12, 'T');
    if (abs >= 1e9) return fmt(n / 1e9, 'B');
    if (abs >= 1e6) return fmt(n / 1e6, 'M');
    if (abs >= 1e3) return fmt(n / 1e3, 'K');
    return d3.format(',.0f')(n);
  }

  // FNV-1a hash for stable pseudo-randomness.
  function stableHash(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i += 1) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function mulberry32(a) {
    return function () {
      let t = (a += 0x6D2B79F5);
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function tooltipMove(event) {
    const pad = 12;
    const box = tooltip.node().getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let x = event.clientX + pad;
    let y = event.clientY + pad;
    if (x + box.width + pad > vw) x = vw - box.width - pad;
    if (y + box.height + pad > vh) y = vh - box.height - pad;

    tooltip.style('transform', `translate(${x}px, ${y}px)`);
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
    tooltip.style('transform', 'translate(-9999px, -9999px)');
    tooltip.html('');
  }

  async function loadHistory(ticker) {
    if (historyCache.has(ticker)) return historyCache.get(ticker);

    const rows = await d3.csv(`${DATA_PATH.historyDir}/${ticker}.csv`, (d) => ({
      date: d3.timeParse('%Y-%m-%d')(d.Date),
      adjClose: toNumber(d['Adjusted Close'])
    }));

    const cleaned = rows
      .filter((d) => d.date instanceof Date && Number.isFinite(d.adjClose))
      .sort((a, b) => a.date - b.date);

    historyCache.set(ticker, cleaned);
    return cleaned;
  }

  function renderSparkline(containerSel, series) {
    const w = 260;
    const h = 44;
    containerSel
      .attr('viewBox', `0 0 ${w} ${h}`)
      .attr('preserveAspectRatio', 'none');

    containerSel.selectAll('*').remove();

    if (!series || series.length < 2) return;

    const data = series.slice(-260);

    const x = d3.scaleTime()
      .domain(d3.extent(data, (d) => d.date))
      .range([0, w]);

    const y = d3.scaleLinear()
      .domain(d3.extent(data, (d) => d.adjClose))
      .nice()
      .range([h - 2, 2]);

    const line = d3.line()
      .x((d) => x(d.date))
      .y((d) => y(d.adjClose))
      .curve(d3.curveMonotoneX);

    containerSel.append('path')
      .attr('d', line(data))
      .attr('fill', 'none')
      .attr('stroke', 'rgba(255,255,255,0.85)')
      .attr('stroke-width', 1.25);

    containerSel.append('path')
      .attr('d', `M0,${y(data[data.length - 1].adjClose)} H${w}`)
      .attr('fill', 'none')
      .attr('stroke', 'rgba(255,255,255,0.16)')
      .attr('stroke-width', 1);
  }

  function setSelected(ticker) {
    selectedTicker = ticker;

    tableBody.selectAll('tr')
