      .on('mousemove', (event, d) => {
        if (d.isETF) return;
        tooltipMove(event);
      })
      .on('mouseout', (event, d) => {
        if (d.isETF) return;
        hideTooltip();
      });

    enter.append('circle')
      .attr('r', (d) => d.radius)
      .attr('fill', (d) => color(d.sector));

    enter.append('text')
      .text((d) => d.ticker);

    const merged = enter.merge(bubbles);
    merged.attr('transform', (d) => `translate(${d.x},${d.y})`);

    bubbles.exit().remove();

    svg.on('click', () => setSelected(null));
  }

  async function main() {
    const raw = await d3.csv(DATA_PATH.descriptions, (d) => {
      const sector = (d.sector || '').trim();
      const marketCap = toNumber(d.marketCap);
      const isETF = sector === 'ETF' || !Number.isFinite(marketCap);

      return {
        ticker: (d.ticker || '').trim(),
        sector: sector || 'Unknown',
        fullName: (d['full name'] || '').trim(),
        marketCap,
        isETF
      };
    });

    const stocks = raw
      .filter((d) => d.ticker)
      .sort((a, b) => d3.ascending(a.ticker, b.ticker));

    buildTable(stocks);
    buildBubbleChart(stocks);

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        hideTooltip();
        setSelected(null);
      }
    });

    window.addEventListener('resize', () => buildBubbleChart(stocks));
  }

  main().catch((e) => {
    // eslint-disable-next-line no-console
    console.error(e);
    tooltip
      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .style('transform', 'translate(16px, 16px)')
      .html('<div class="tt-title">Failed to load data</div><div class="tt-sub">Open the browser console for details.</div>');
  });
})();
