{"summary": "Create stylesheet for layout, table, tooltip, and selections", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
  --bg: #0b1020;
  --panel: #111a33;
  --text: #e7ecff;
  --muted: rgba(231, 236, 255, 0.72);
  --grid: rgba(231, 236, 255, 0.12);
  --accent: #8aa0ff;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(1200px 600px at 10% 10%, #13214b 0%, var(--bg) 60%);
  color: var(--text);
}

.app-header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--grid);
  background: rgba(17, 26, 51, 0.65);
  backdrop-filter: blur(10px);
}

.app-title {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.2px;
}

.app-subtitle {
  margin-top: 4px;
  font-size: 13px;
  color: var(--muted);
}

.layout {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(17,26,51,0.9) 0%, rgba(17,26,51,0.65) 100%);
  border: 1px solid var(--grid);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 18px 40px rgba(0,0,0,0.35);
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--grid);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.panel-title {
  margin: 0;
  font-size: 14px;
  letter-spacing: 0.2px;
}

.panel-hint {
  font-size: 12px;
  color: var(--muted);
}

.panel-chart {
  flex: 1 1 58%;
  min-width: 520px;
}

.panel-table {
  flex: 1 1 42%;
  min-width: 420px;
}

.chart-wrap {
  padding: 10px;
}

.chart-svg {
  width: 100%;
  height: 640px;
  display: block;
  border-radius: 12px;
  background: rgba(5, 8, 18, 0.35);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  justify-content: flex-end;
}

.legend-item {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.25);
}

.table-wrap {
  max-height: 680px;
  overflow: auto;
}

.stock-table {
  width: 100%;
  border-collapse: collapse;
}

.stock-table thead th {
  position: sticky;
  top: 0;
  background: rgba(11, 16, 32, 0.9);
  backdrop-filter: blur(8px);
  text-align: left;
  font-size: 12px;
  font-weight: 700;
  padding: 10px 10px;
  border-bottom: 1px solid var(--grid);
  color: var(--text);
}

.stock-table tbody td {
  padding: 10px;
  border-bottom: 1px solid var(--grid);
  font-size: 12px;
  color: rgba(231,236,255,0.9);
}

.stock-table tbody tr {
  cursor: pointer;
}

.stock-table tbody tr:hover {
  background: rgba(138,160,255,0.10);
}

.stock-table tbody tr.selected {
  background: rgba(138,160,255,0.22);
  outline: 1px solid rgba(138,160,255,0.55);
  outline-offset: -1px;
}

.tooltip {
  position: fixed;
  left: 0;
  top: 0;
  transform: translate(-9999px, -9999px);
  opacity: 0;
  pointer-events: none;
  padding: 10px 10px;
  border-radius: 10px;
  max-width: 320px;
  background: rgba(0,0,0,0.86);
  border: 1px solid rgba(255,255,255,0.18);
  box-shadow: 0 10px 30px rgba(0,0,0,0.45);
  color: #fff;
}

.tooltip.visible {
  opacity: 1;
}

.tooltip .tt-title {
  font-size: 13px;
  font-weight: 800;
}

.tooltip .tt-sub {
  margin-top: 4px;
  font-size: 12px;
  color: rgba(255,255,255,0.85);
}

.tooltip .spark {
  display: block;
  margin-top: 8px;
  width: 100%;
  height: 44px;
}

.bubble circle {
  stroke: rgba(255,255,255,0.18);
  stroke-width: 1px;
}

.bubble.selected circle {
  stroke: #ffffff;
  stroke-width: 2.5px;
}

.bubble text {
  fill: rgba(255,255,255,0.92);
  font-weight: 800;
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
