          .attr('aria-hidden', 'false');

        tooltipMove(event);

        try {
          const series = await loadHistory(d.ticker);
          renderSparkline(tooltip.select('svg.spark'), series);
        } catch (e) {
          // If a history file is missing, keep the tooltip text only.
        }
      })
      .on('mousemove', (event, d) => {
        if (d.isETF) return;
        tooltipMove(event);
      })
      .on('mouseout', (event, d) => {
        if (d.isETF) return;
        hideTooltip();
      });

