      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .style('transform', 'translate(16px, 16px)')
      .html('<div class="tt-title">Failed to load data</div><div class="tt-sub">Open the browser console for details.</div>');
  });
})();
