        except ValueError:
            mc=None
        stocks.append({
            'ticker': ticker,
            'sector': sector,
            'fullName': full_name,
            'marketCap': mc,
        })

histories={}
for p in sorted(glob.glob(hist_glob)):
    stem=os.path.splitext(os.path.basename(p))[0]
    ticker=stem.upper()
    rows=[]
    with open(p,newline='',encoding='utf-8') as f:
