* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(1200px 600px at 10% 10%, #13214b 0%, var(--bg) 60%);
  color: var(--text);
}

.app-header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--grid);
  background: rgba(17, 26, 51, 0.65);
  backdrop-filter: blur(10px);
}

.app-title {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.2px;
}

.app-subtitle {
  margin-top: 4px;
  font-size: 13px;
  color: var(--muted);
}

.layout {
  display: flex;
  gap: 14px;
  padding: 14px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(17,26,51,0.9) 0%, rgba(17,26,51,0.65) 100%);
  border: 1px solid var(--grid);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 18px 40px rgba(0,0,0,0.35);
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--grid);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.panel-title {
  margin: 0;
  font-size: 14px;
  letter-spacing: 0.2px;
}

.panel-hint {
  font-size: 12px;
  color: var(--muted);
}

.panel-chart {
  flex: 1 1 58%;
  min-width: 520px;
}

.panel-table {
  flex: 1 1 42%;
  min-width: 420px;
}

.chart-wrap {
  padding: 10px;
}

.chart-svg {
  width: 100%;
  height: 640px;
  display: block;
  border-radius: 12px;
  background: rgba(5, 8, 18, 0.35);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  justify-content: flex-end;
}

.legend-item {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.25);
}

.table-wrap {
  max-height: 680px;
  overflow: auto;
}

.stock-table {
  width: 100%;
  border-collapse: collapse;
}

.stock-table thead th {
  position: sticky;
  top: 0;
  background: rgba(11, 16, 32, 0.9);
  backdrop-filter: blur(8px);
  text-align: left;
  font-size: 12px;
  font-weight: 700;
  padding: 10px 10px;
  border-bottom: 1px solid var(--grid);
  color: var(--text);
}

.stock-table tbody td {
  padding: 10px;
  border-bottom: 1px solid var(--grid);
  font-size: 12px;
  color: rgba(231,236,255,0.9);
}

.stock-table tbody tr {
  cursor: pointer;
}

.stock-table tbody tr:hover {
  background: rgba(138,160,255,0.10);
}

.stock-table tbody tr.selected {
  background: rgba(138,160,255,0.22);
  outline: 1px solid rgba(138,160,255,0.55);
  outline-offset: -1px;
}

.tooltip {
  position: fixed;
  left: 0;
  top: 0;
  transform: translate(-9999px, -9999px);
  opacity: 0;
  pointer-events: none;
  padding: 10px 10px;
  border-radius: 10px;
  max-width: 320px;
  background: rgba(0,0,0,0.86);
  border: 1px solid rgba(255,255,255,0.18);
  box-shadow: 0 10px 30px rgba(0,0,0,0.45);
  color: #fff;
}

.tooltip.visible {
  opacity: 1;
}

.tooltip .tt-title {
  font-size: 13px;
  font-weight: 800;
}

.tooltip .tt-sub {
  margin-top: 4px;
  font-size: 12px;
  color: rgba(255,255,255,0.85);
}

.tooltip .spark {
  display: block;
  margin-top: 8px;
  width: 100%;
  height: 44px;
}

.bubble circle {
  stroke: rgba(255,255,255,0.18);
  stroke-width: 1px;
}

.bubble.selected circle {
  stroke: #ffffff;
  stroke-width: 2.5px;
}

.bubble text {
  fill: rgba(255,255,255,0.92);
  font-weight: 800;
  font-size: 11px;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.55);
  stroke-width: 2px;
}

@media (max-width: 1080px) {
  .layout { flex-direction: column; }
  .panel-chart, .panel-table { min-width: unset; }
  .chart-svg { height: 560px; }
}
"}

{"summary": "Add D3 visualization logic for bubble chart, table, and interactions", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */

(() => {
  const DATA_PATH = {
    descriptions: 'data/stock-descriptions.csv',
    historyDir: 'data/indiv-stock'
  };

  const svg = d3.select('#bubble-svg');
  const legendEl = d3.select('#legend');
  const tableBody = d3.select('#stock-table tbody');
  const tooltip = d3.select('#tooltip');

  const historyCache = new Map();
  let selectedTicker = null;

  function toNumber(v) {
    if (v == null) return NaN;
    const s = String(v).trim();
    if (!s) return NaN;
    const n = Number(s);
    return Number.isFinite(n) ? n : NaN;
  }

  function formatMarketCap(n) {
    if (!Number.isFinite(n)) return '—';
    const abs = Math.abs(n);
    const fmt = (x, unit) => `${d3.format('.3~g')(x)}${unit}`;
    if (abs >= 1e12) return fmt(n / 1e12, 'T');
    if (abs >= 1e9) return fmt(n / 1e9, 'B');
    if (abs >= 1e6) return fmt(n / 1e6, 'M');
    if (abs >= 1e3) return fmt(n / 1e3, 'K');
    return d3.format(',.0f')(n);
  }

  // FNV-1a hash for stable pseudo-randomness.
  function stableHash(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i += 1) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return h >>> 0;
  }

  function mulberry32(a) {
    return function () {
      let t = (a += 0x6D2B79F5);
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function tooltipMove(event) {
    const pad = 12;
    const box = tooltip.node().getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let x = event.clientX + pad;
    let y = event.clientY + pad;
    if (x + box.width + pad > vw) x = vw - box.width - pad;
    if (y + box.height + pad > vh) y = vh - box.height - pad;

    tooltip.style('transform', `translate(${x}px, ${y}px)`);
  }

  function hideTooltip() {
    tooltip.classed('visible', false).attr('aria-hidden', 'true');
    tooltip.style('transform', 'translate(-9999px, -9999px)');
    tooltip.html('');
  }

  async function loadHistory(ticker) {
    if (historyCache.has(ticker)) return historyCache.get(ticker);

    const rows = await d3.csv(`${DATA_PATH.historyDir}/${ticker}.csv`, (d) => ({
      date: d3.timeParse('%Y-%m-%d')(d.Date),
      adjClose: toNumber(d['Adjusted Close'])
    }));

    const cleaned = rows
      .filter((d) => d.date instanceof Date && Number.isFinite(d.adjClose))
      .sort((a, b) => a.date - b.date);

    historyCache.set(ticker, cleaned);
    return cleaned;
  }

  function renderSparkline(containerSel, series) {
    const w = 260;
    const h = 44;
    containerSel
      .attr('viewBox', `0 0 ${w} ${h}`)
      .attr('preserveAspectRatio', 'none');

    containerSel.selectAll('*').remove();

    if (!series || series.length < 2) return;

    const data = series.slice(-260);

    const x = d3.scaleTime()
      .domain(d3.extent(data, (d) => d.date))
      .range([0, w]);

    const y = d3.scaleLinear()
      .domain(d3.extent(data, (d) => d.adjClose))
      .nice()
      .range([h - 2, 2]);

    const line = d3.line()
      .x((d) => x(d.date))
      .y((d) => y(d.adjClose))
      .curve(d3.curveMonotoneX);

    containerSel.append('path')
      .attr('d', line(data))
      .attr('fill', 'none')
      .attr('stroke', 'rgba(255,255,255,0.85)')
      .attr('stroke-width', 1.25);

    containerSel.append('path')
      .attr('d', `M0,${y(data[data.length - 1].adjClose)} H${w}`)
      .attr('fill', 'none')
      .attr('stroke', 'rgba(255,255,255,0.16)')
      .attr('stroke-width', 1);
  }

  function setSelected(ticker) {
    selectedTicker = ticker;

    tableBody.selectAll('tr')
      .classed('selected', (d) => d.ticker === selectedTicker);

    svg.selectAll('g.bubble')
      .classed('selected', (d) => d.ticker === selectedTicker);

    const row = tableBody.selectAll('tr').filter((d) => d.ticker === selectedTicker);
    const node = row.node();
    if (node) node.scrollIntoView({ block: 'center' });
  }

  function buildLegend(sectors, color) {
    const items = legendEl.selectAll('.legend-item')
      .data(sectors, (d) => d);

    const enter = items.enter().append('div').attr('class', 'legend-item');
    enter.append('span').attr('class', 'legend-swatch');
    enter.append('span').attr('class', 'legend-label');

    const merged = enter.merge(items);
    merged.select('.legend-swatch').style('background', (d) => color(d));
    merged.select('.legend-label').text((d) => d);

    items.exit().remove();
  }

  function buildTable(stocks) {
    const rows = tableBody.selectAll('tr')
      .data(stocks, (d) => d.ticker);

    const enter = rows.enter().append('tr')
      .on('click', (event, d) => {
        setSelected(d.ticker);
      });

    enter.append('td').attr('class', 'col-ticker');
    enter.append('td').attr('class', 'col-name');
    enter.append('td').attr('class', 'col-sector');
    enter.append('td').attr('class', 'col-mc');

    const merged = enter.merge(rows);
    merged.select('.col-ticker').text((d) => d.ticker);
    merged.select('.col-name').text((d) => d.fullName);
    merged.select('.col-sector').text((d) => d.sector);
    merged.select('.col-mc').text((d) => formatMarketCap(d.marketCap));

    rows.exit().remove();
  }

  function buildBubbleChart(stocks) {
    const box = svg.node().getBoundingClientRect();
    const width = Math.max(520, Math.floor(box.width));
    const height = 640;
    svg.attr('viewBox', `0 0 ${width} ${height}`);

    const sectors = Array.from(new Set(stocks.map((d) => d.sector))).sort(d3.ascending);

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeTableau10.slice(0, sectors.length));

    buildLegend(sectors, color);

    const caps = stocks.filter((d) => !d.isETF && Number.isFinite(d.marketCap)).map((d) => d.marketCap);
    const capExtent = d3.extent(caps);
    const rETF = 16;
    const rScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([12, 56])
      .clamp(true);

    const cx = width / 2;
    const cy = height / 2;
    const ring = Math.min(width, height) * 0.26;

    const sectorCenters = new Map();
    sectors.forEach((s, i) => {
      const angle = (i / sectors.length) * Math.PI * 2;
      sectorCenters.set(s, {
        x: cx + ring * Math.cos(angle),
        y: cy + ring * Math.sin(angle)
      });
    });

    const nodes = stocks.map((d) => {
      const seed = stableHash(d.ticker);
      const rand = mulberry32(seed);
      const c = sectorCenters.get(d.sector) || { x: cx, y: cy };
      const a = rand() * Math.PI * 2;
      const j = 10 + rand() * 26;

      return {
        ...d,
        radius: d.isETF ? rETF : rScale(d.marketCap),
        x: c.x + j * Math.cos(a),
        y: c.y + j * Math.sin(a)
      };
    });

    const simulation = d3.forceSimulation(nodes)
      .force('x', d3.forceX((d) => sectorCenters.get(d.sector).x).strength(0.18))
      .force('y', d3.forceY((d) => sectorCenters.get(d.sector).y).strength(0.18))
      .force('collide', d3.forceCollide((d) => d.radius + 1.6).iterations(2))
      .force('charge', d3.forceManyBody().strength(-8))
      .force('center', d3.forceCenter(cx, cy))
      .stop();

    for (let i = 0; i < 320; i += 1) simulation.tick();

    const bubbles = svg.selectAll('g.bubble')
      .data(nodes, (d) => d.ticker);

    const enter = bubbles.enter().append('g')
      .attr('class', 'bubble')
      .attr('transform', (d) => `translate(${d.x},${d.y})`)
      .on('click', (event, d) => {
        setSelected(d.ticker);
        event.stopPropagation();
      })
      .on('mouseover', async (event, d) => {
        if (d.isETF) return;

        tooltip
          .html(
            `<div class="tt-title">${d.ticker}</div>` +
            `<div class="tt-sub">${d.fullName}</div>` +
            `<div class="tt-sub">Sector: ${d.sector}</div>` +
            `<svg class="spark"></svg>`
          )
          .classed('visible', true)
          .attr('aria-hidden', 'false');

        tooltipMove(event);

        try {
          const series = await loadHistory(d.ticker);
          renderSparkline(tooltip.select('svg.spark'), series);
        } catch (e) {
