      .map(([date, adjClose]) => ({{ date: parseDate(date), adjClose: toNumber(adjClose) }}))
      .filter((d) => d.date instanceof Date && Number.isFinite(d.adjClose))
      .sort((a, b) => a.date - b.date);

    historyCache.set(key, cleaned);
